insert into public.expo_problems
  (slug, title, crop_key, symptom_keys, summary, cause, actions, principle, product_keywords, no_products, seasonal, video_url, image_urls, source_label, video_title, video_source, video_start)
values
  ('gochu-thrips', '고추 총채벌레', 'gochu', array['insects', 'spots']::text[], '새잎이 오그라들고 꽃이 떨어지며 열매에 흰 긁힌 자국', '총채벌레가 새순·꽃·어린 열매를 빨아 먹고, 바이러스(TSWV)를 옮깁니다.', array['끝잎과 꽃 속을 털어 흰 종이에 받아 보면 작은 벌레가 움직입니다. 주 1회 확인', '발생 초기에 해충 관리 자재를 쓰고, 한 가지 계통만 반복하지 않습니다', '하우스는 출입구·측창에 방충망, 주변 잡초 제거']::text[], '총채벌레는 숨는 곳이 많아 초기 발견과 계통을 바꿔 가며 관리하는 것이 핵심입니다.', array['총채', '해충', '살충', '진딧물', '응애']::text[], false, false, 'https://www.youtube.com/watch?v=8KTyTB7LcVc', '{}', null, '어떤 약을 쳐도 총채벌레가 잘 안 죽어요?', 'kaftv', null),
  ('gochu-anthracnose', '고추 탄저병', 'gochu', array['spots']::text[], '열매에 움푹 파인 둥근 반점, 장마·비 온 뒤 급격히 번짐', '곰팡이병으로 빗물에 포자가 튀어 번집니다. 병든 열매를 그대로 두면 다음 해까지 이어집니다.', array['병든 열매는 바로 따서 밭 밖으로 — 땅에 떨어진 것도 치웁니다', '비 오기 전·후로 균 관리 자재를 예방 위주로 씁니다', '통풍이 되게 곁순 정리, 고랑에 물이 고이지 않게']::text[], '탄저병은 치료보다 예방입니다. 비 전후 관리와 병든 열매 제거가 자재보다 먼저입니다.', array['탄저', '살균', '균', '병해', '곰팡이']::text[], false, false, 'https://www.youtube.com/watch?v=on6ah3HG-2Y', '{}', null, '고추 탄저병 예방부터 일소 피해까지', 'kaftv', null),
  ('gochu-aphid-virus', '고추 진딧물·바이러스', 'gochu', array['insects', 'yellow-leaf']::text[], '잎 뒷면에 진딧물, 새잎이 쭈글쭈글 모자이크 무늬', '진딧물이 즙을 빨며 바이러스를 옮깁니다. 바이러스는 걸리면 치료가 안 됩니다.', array['바이러스 증상 포기는 뽑아서 밭 밖으로 (전염원 제거)', '진딧물은 발생 초기에 잎 뒷면 위주로 관리', '은색 멀칭·방충망으로 날아드는 것을 줄입니다']::text[], '바이러스 자체는 약이 없습니다. 매개충(진딧물) 관리와 병든 포기 제거가 전부입니다.', array['진딧물', '해충', '살충', '총채']::text[], false, false, 'https://www.youtube.com/watch?v=SN21fqSxbTU', '{}', null, '바이러스 걸린 고추와 안 걸린 고추가 공생한다?', 'kaftv', null),
  ('garlic-rooting', '마늘 정식 후 뿌리 내림 불량', 'garlic', array['root', 'growth']::text[], '심은 지 2~3주가 지나도 싹이 고르지 않고 뽑아 보면 뿌리가 짧다', '토양 수분 부족이나 과습, 깊이 심기, 종구 상태 불량이 겹칩니다.', array['몇 포기 뽑아 뿌리 길이를 봅니다. 흰 뿌리가 손가락 한 마디 이상이면 정상', '건조하면 충분히 관수, 과습이면 배수로를 먼저 정리', '뿌리 활착을 돕는 영양 자재는 토양이 적당히 젖은 상태에서']::text[], '정식 후 뿌리 내림은 수분 관리가 8할입니다. 자재는 그 다음입니다.', array['뿌리', '활착', '발근', '아미노', '마늘', '양파']::text[], false, true, 'https://www.youtube.com/watch?v=AInSqy8Huko', '{}', null, '뿌리 발근에 제일 좋은 건?', 'kaftv', null),
  ('garlic-onion-overwinter', '마늘·양파 월동 준비', 'garlic', array['growth']::text[], '12월 추위 전에 뿌리를 충분히 내리게 하고 피복으로 보온', '뿌리가 덜 내린 채 얼면 봄에 들뜨고 결주가 납니다.', array['비닐·부직포 피복은 땅이 얼기 전에. 구멍 뚫린 피복은 바람에 날리지 않게 고정', '배수로를 다시 치고 고랑에 물이 서지 않게', '월동 전 과한 질소는 피하고, 뿌리 중심의 영양 공급']::text[], '월동은 ''뿌리가 얼마나 내렸나''와 ''물이 고이지 않나'' 두 가지로 결정됩니다.', array['월동', '뿌리', '활착', '마늘', '양파', '부직포', '피복']::text[], false, true, 'https://www.youtube.com/watch?v=dPO-7tZF7CI', '{}', null, '월동 마늘·양파 추비는 이렇게', 'dof', null),
  ('garlic-black-mold', '마늘 흑색썩음균핵병·잎마름', 'garlic', array['mold', 'yellow-leaf']::text[], '봄에 잎이 아래부터 노래지고 뽑으면 구 밑에 검은 균핵', '토양 전염 곰팡이병. 연작 밭에서 심하고, 한번 들면 여러 해 갑니다.', array['병든 포기는 흙째 들어내 밭 밖으로', '연작 밭은 심기 전 토양 처리와 윤작을 고려', '배수가 나쁜 곳부터 발생하므로 배수로 정비']::text[], '토양병은 심기 전 예방이 거의 전부입니다. 발생 후에는 확산을 늦추는 관리입니다.', array['균핵', '토양', '살균', '마늘']::text[], false, false, 'https://www.youtube.com/watch?v=Nce3rVd1gnc', '{}', null, '뿌리썩음병·균핵병 — 싹쓰리쏘일', 'dof', null),
  ('onion-downy-mildew', '양파 노균병', 'onion', array['mold', 'yellow-leaf']::text[], '잎에 타원형 연한 반점, 아침이슬 때 회백색 곰팡이', '서늘하고 습한 날이 이어질 때 번지는 곰팡이병. 가을 감염이 봄에 터집니다.', array['가을 정식 후부터 예방 관리, 봄 비 온 뒤 다시 점검', '병든 잎은 따서 밭 밖으로, 밀식을 피해 통풍', '질소 과다 금지, 배수로 정비']::text[], '노균병은 습도와 질소가 키웁니다. 통풍과 비 전후 관리가 기본입니다.', array['노균', '살균', '균', '양파']::text[], false, false, 'https://www.youtube.com/watch?v=DdvnKSrdPxM', '{}', null, '노균병 걸린 양파밭에 더운날 물 줘도 되나?', 'kaftv', null),
  ('apple-postharvest', '사과 수확 후 나무 회복', 'apple', array['growth']::text[], '수확으로 지친 나무에 낙엽 전까지 저장양분을 채워야 내년 꽃눈이 좋다', '수확 직후 잎이 살아 있는 동안 만든 양분이 뿌리·가지에 저장돼 내년 개화·착과를 좌우합니다.', array['잎이 붙어 있는 동안 엽면 영양 공급 (낙엽 후엔 효과 없음)', '토양 수분 유지, 가을 거름은 낙엽 전후 적기에', '병든 낙엽·낙과는 모아 처리해 내년 전염원 줄이기']::text[], '사과 농사의 내년은 올해 11월에 결정됩니다. 잎이 있을 때 저장양분을 채우는 것이 핵심입니다.', array['아미노', '수확 후', '회복', '엽면', '사과', '영양']::text[], false, true, 'https://www.youtube.com/watch?v=sBs8Si_pILY', '{}', null, '사과, 수확 끝났다고 손 놓으면 내년 꽃눈이 얼어요', 'kaftv', null),
  ('apple-coloring', '사과 착색 불량', 'apple', array['poor-color']::text[], '수확기가 다가오는데 붉은색이 늦고 얼룩진다', '일조 부족, 일교차 부족, 질소 과다, 잎에 가려짐이 겹칩니다.', array['열매 주변 잎 따기·반사필름으로 빛을 들입니다', '질소는 수확 6주 전부터 끊습니다', '착색 보조 자재는 수확 3~4주 전, 기온이 내려간 뒤']::text[], '착색은 빛·온도·질소 세 가지가 먼저이고, 자재는 마지막 보조입니다.', array['착색', '사과', '안토시아닌', '색']::text[], false, false, 'https://www.youtube.com/watch?v=Bq0UTWgALOU', '{}', null, '40년 사과 장인의 착색 혁명', 'kaftv', null),
  ('strawberry-mite', '딸기 응애', 'strawberry', array['insects', 'yellow-leaf']::text[], '잎이 누렇게 바래고 뒷면에 거미줄 같은 것, 생육이 멈춤', '점박이응애가 잎 뒷면에서 즙을 빨아 먹습니다. 고온 건조한 시설에서 폭발적으로 늡니다.', array['정식 직후부터 잎 뒷면을 돋보기로 주 1회 확인', '발생 초기에 관리하고 계통을 바꿔 씁니다. 천적(칠레이리응애) 활용도 검토', '하우스 습도를 너무 낮추지 않고, 마른 잎 제거']::text[], '응애는 늘어난 뒤에는 잡기 어렵습니다. 정식 직후 초기 관리가 한 해를 결정합니다.', array['응애', '해충', '살비', '딸기', '천적']::text[], false, true, 'https://www.youtube.com/watch?v=I0L2TfrOeW0', '{}', null, '골치 아픈 응애 한 방에 보내는 법', 'kaftv', null),
  ('strawberry-powdery-gray', '딸기 흰가루병·잿빛곰팡이', 'strawberry', array['mold']::text[], '잎·열매에 흰 가루, 또는 열매에 회색 곰팡이가 피어 물러짐', '흰가루병은 건조할 때, 잿빛곰팡이는 습할 때. 환기와 습도 관리가 어긋나면 번갈아 옵니다.', array['아침 환기로 결로를 없애고, 병든 잎·열매는 즉시 제거', '밀식·과번무를 피하고 늙은 잎 정리', '예방 위주 균 관리, 수확기엔 안전사용 기준 확인']::text[], '두 병은 습도 관리로 같이 잡습니다. 환기 시간과 늙은 잎 정리가 자재보다 먼저입니다.', array['흰가루', '잿빛', '살균', '균', '딸기']::text[], false, false, 'https://www.youtube.com/watch?v=muRqMImFE6U', '{}', null, '흰가루 걱정 끝!!', 'kaftv', null),
  ('strawberry-malformed', '딸기 기형과·수정 불량', 'strawberry', array['growth']::text[], '열매가 울퉁불퉁하거나 끝이 뭉뚝, 씨가 한쪽에 몰림', '벌 활동 부족(저온·흐린 날·약제 영향), 꽃가루 불량, 초기 영양 불균형', array['벌통 상태와 활동 시간 확인, 약제 살포는 벌 활동 시간을 피해', '개화기 야간 온도가 너무 낮지 않게', '초기 생육 영양(특히 붕소·칼슘) 결핍 여부 점검']::text[], '기형과는 ''벌''과 ''온도''가 7할입니다. 자재는 영양 균형을 돕는 보조입니다.', array['붕소', '칼슘', '개화', '수정', '딸기']::text[], false, false, null, '{}', null, null, null, null),
  ('tomato-cracking', '토마토 열과(갈라짐)', 'tomato', array['fruit-crack']::text[], '익어 가는 열매 꼭지 주변이 방사형·동심원으로 갈라진다', '건조하다가 갑자기 물이 많아질 때, 과육이 껍질보다 빨리 커지며 터집니다.', array['관수 간격을 일정하게 — 한 번에 많이보다 자주 조금', '급격한 온도 변화와 직사광 피하기(차광)', '칼슘·칼륨 균형 공급, 질소 과다 주의']::text[], '열과는 물 관리의 문제입니다. 자재는 껍질 강화와 균형을 돕는 역할입니다.', array['열과', '칼슘', '터짐', '토마토', '아미노']::text[], false, false, null, '{}', null, null, null, null),
  ('tomato-blossom-end-rot', '토마토 배꼽썩음(칼슘 결핍)', 'tomato', array['spots']::text[], '풋열매 밑동(꽃 떨어진 자리)이 움푹 꺼지며 갈색·검게 마른다', '흙에 칼슘이 있어도 물이 끊기거나 질소·칼리가 많으면 열매 끝까지 칼슘이 못 갑니다. 대부분 물 관리 문제입니다.', array['상한 열매는 바로 따서 밭 밖으로 — 다시 낫지 않고 곰팡이만 번집니다', '칼슘제를 열매·새잎에 엽면시비 — 라벨 배수(보통 500~1,000배), 5~7일 간격 2~3회, 해 질 무렵', '물은 ''말랐다 흠뻑'' 말고 조금씩 자주, 질소 웃거름은 잠시 멈춤']::text[], '칼슘은 뿌린 자리에만 들어가고 옆으로 옮겨 가지 않습니다. 열매에 직접 닿게, 여러 번 나눠 주는 게 요령입니다.', array['칼슘', '배꼽', '고두', '토마토', '엽면']::text[], false, true, 'https://www.youtube.com/watch?v=lNGJCI3SUiU', '{}', null, '탄저인가? 칼슘결핍인가? 구분하는 법', 'kaftv', null),
  ('tomato-leaf-mold', '토마토 잎곰팡이병', 'tomato', array['spots', 'mold']::text[], '잎 앞면에 연노란 얼룩, 뒷면엔 갈색·올리브색 벨벳 같은 곰팡이가 핀다', '하우스 습도가 85% 넘게 오래 가면 번집니다. 밤에 문 닫고 보온할 때, 잎이 빽빽할 때 잘 생깁니다.', array['오늘 아랫잎·병든 잎을 따서 비닐에 담아 밖으로 — 잎 사이로 바람이 지나가게', '아침 해 뜬 뒤 30분~1시간 환기, 밤엔 살짝 난방해 잎이 젖지 않게(습도 85% 아래)', '등록 약제를 라벨 배수대로 잎 뒷면까지 7~10일 간격 2~3회, 계통 바꿔 가며']::text[], '잎곰팡이는 습도 병입니다. 약보다 환기·잎 정리가 먼저이고, 공시 자재(구리제 등)는 예방용입니다. 이미 번졌으면 등록 농약을 쓰세요.', array['잎곰팡이', '곰팡이', '토마토', '보르도', '살균']::text[], false, true, null, '{}', null, null, null, null),
  ('tomato-early-blight', '토마토 겹둥근무늬병', 'tomato', array['spots']::text[], '아랫잎부터 갈색 반점에 과녁처럼 겹겹이 둥근 무늬, 둘레가 노랗게 변한다', '덥고 습할 때, 그리고 거름이 떨어져 포기가 지쳤을 때 아랫잎부터 올라옵니다. 병든 잎에서 물방울로 튀어 번집니다.', array['무늬 생긴 아랫잎은 오늘 따서 밖으로 — 밭에 두면 다시 퍼집니다', '웃거름이 떨어지지 않게(질소·가리 적정), 물은 잎에 튀지 않게 포기 밑으로', '등록 약제를 라벨 배수대로 7~10일 간격, 계통 바꿔 가며 / 다음 작기엔 잔재 치우고 돌려짓기']::text[], '겹둥근무늬병은 지친 포기에 잘 옵니다. 병든 잎 제거와 거름 관리가 기본이고, 공시 자재(구리제 등)는 번지기 전 예방용입니다.', array['겹둥근무늬', '토마토', '보르도', '살균']::text[], false, false, null, '{}', null, null, null, null),
  ('tomato-gray-mold', '토마토 잿빛곰팡이병', 'tomato', array['mold', 'spots']::text[], '시든 꽃잎·열매 꽃자리부터 물러지며 잿빛 곰팡이가 뽀얗게 덮인다', '선선하고(15~20℃) 습한 가을·겨울 하우스에서 잘 생깁니다. 떨어지지 않은 꽃잎과 상처에서 시작합니다.', array['병든 열매·잎은 비닐봉지에 조심히 담아 밖으로 — 털면 포자가 날립니다', '열매에 붙은 시든 꽃잎 떼기, 곁순·아랫잎 정리로 통풍', '밤 습도 낮추기(환기·약한 난방) + 등록 약제를 라벨대로, 내성 잘 생기니 계통 꼭 바꿔 가며']::text[], '잿빛곰팡이는 습기와 시든 꽃잎에서 시작합니다. 환경 관리가 먼저이고, 공시 미생물 자재는 예방용입니다.', array['잿빛곰팡이', '곰팡이', '토마토', '세레나데', '미생물']::text[], false, true, null, '{}', null, null, null, null),
  ('tomato-cucumber-whitefly', '토마토·오이 가루이(온실가루이)', 'tomato', array['insects']::text[], '잎을 건드리면 흰 작은 벌레가 날아오르고, 잎에 끈적한 분비물·그을음', '온실가루이가 잎 뒷면에서 즙을 빨고 바이러스(TYLCV)를 옮깁니다.', array['황색 끈끈이트랩을 작물 위 20cm에 걸어 발생을 먼저 봅니다', '알·약충이 잎 뒷면에 있으니 뒷면까지 닿게 관리, 계통 교대', '하우스 출입구 방충망, 묘 반입 때 확인']::text[], '가루이는 성충만 잡으면 다시 나옵니다. 알·약충 단계까지 잡는 반복 관리가 핵심입니다.', array['가루이', '해충', '살충', '끈끈이', '토마토', '오이']::text[], false, false, 'https://www.youtube.com/watch?v=2kLuZght2E4', '{}', null, '온실가루이·담배가루이 고민 해결', 'kaftv', null),
  ('cucumber-downy-mildew', '오이 노균병', 'cucumber', array['mold', 'yellow-leaf']::text[], '잎맥에 막힌 각진 노란 반점, 뒷면에 회색 곰팡이', '습하고 서늘할 때 급속히 번지는 곰팡이병. 환기 부족한 시설에서 흔합니다.', array['아침 환기로 잎의 물기를 빨리 말립니다', '아래 늙은 잎부터 번지니 병든 잎 제거', '예방 위주 균 관리, 비 오기 전 점검']::text[], '노균병은 잎이 젖어 있는 시간을 줄이는 것이 전부입니다.', array['노균', '살균', '균', '오이']::text[], false, false, 'https://www.youtube.com/watch?v=UMRuyL0VXFk', '{}', null, '농약 안 치고 노균병 예방하는 식물 프로바이오틱스', 'kaftv', null),
  ('citrus-cracking', '감귤·레드향 열과', 'citrus', array['fruit-crack']::text[], '가을 비 온 뒤 열매가 갈라져 떨어진다, 만감류에 특히 심함', '건조 뒤 급격한 수분 공급으로 과육이 팽창하고, 껍질이 얇은 품종에서 터집니다.', array['가뭄 때 소량씩 관수해 토양 수분 급변을 막습니다', '열매 껍질을 튼튼하게 하는 영양(칼슘·아미노산 계열) 공급', '배수로 정비, 지나친 결실은 적과']::text[], '열과는 ''물의 급변''이 원인입니다. 꾸준한 관수와 껍질 강화가 답입니다.', array['열과', '아미노', '칼슘', '감귤', '레드향', '만감']::text[], false, true, 'https://www.youtube.com/watch?v=SszeFfk6VdU', '{}', null, '열과 피해 할퀴고 간 제주에 희망을 잡은 농부', 'kaftv', null),
  ('cabbage-soft-rot', '배추 무름병', 'cabbage', array['wilting', 'spots']::text[], '밑동부터 물러지며 썩는 냄새, 김장 직전에 포기가 주저앉음', '세균병. 상처·해충 피해 부위로 들어가고, 배수 불량과 고온다습에서 급격히 번집니다.', array['병든 포기는 즉시 뽑아 밭 밖으로, 손·도구 소독', '해충 피해(벼룩잎벌레 등)와 상처를 줄입니다', '배수로 정비, 수확 전 비 온 뒤 점검']::text[], '무름병은 세균이라 곰팡이약이 안 듣습니다. 상처·해충·배수 관리가 먼저입니다.', array['무름', '세균', '배추', '살균']::text[], false, true, 'https://www.youtube.com/watch?v=WBVW-Oj96Bk', '{}', null, '무름병·냉해 극복하고 만평 배추밭 2억 매출', 'kaftv', null),
  ('rice-postharvest-soil', '벼 수확 후 논 관리', 'rice', array['growth']::text[], '볏짚 환원과 월동 녹비로 내년 지력을 만든다', '볏짚을 태우거나 걷어 내면 유기물이 빠져 지력이 떨어집니다.', array['볏짚은 잘게 잘라 깔고 가을갈이로 섞어 넣습니다', '녹비(헤어리베치·호밀 등)는 10월 말~11월 초 파종', '배수 나쁜 논은 배수로를 쳐서 봄 작업을 쉽게']::text[], '지력은 한 해에 안 만들어집니다. 수확 후 유기물 환원이 내년 비료값을 줄입니다.', array['볏짚', '녹비', '토양', '유기물', '로타리', '파쇄']::text[], false, true, 'https://www.youtube.com/watch?v=inrPH1HU_VQ', '{}', null, '연작장해를 피하는 토양 만들기 특강 1부', 'kaftv', null),
  ('paprika-thrips-powdery', '파프리카·시설고추 총채벌레·흰가루병', 'paprika', array['insects', 'mold']::text[], '꽃이 떨어지고 열매에 흰 긁힘, 잎에 흰 가루가 번진다', '밀폐된 하우스에서 총채벌레가 번식하고, 건조하면 흰가루병이 뒤따릅니다.', array['청색·황색 끈끈이트랩으로 발생을 먼저 보고, 꽃 속을 털어 확인', '총채는 계통을 바꿔 가며, 흰가루는 발생 초기에 예방 위주로', '측창 방충망, 하우스 안 습도를 너무 낮추지 않기']::text[], '시설 작물은 밀폐될수록 해충이 폭발합니다. 트랩으로 보고, 초기에 잡고, 계통을 바꿉니다.', array['총채', '흰가루', '해충', '살충', '살균', '끈끈이', '파프리카', '고추']::text[], false, true, 'https://www.youtube.com/watch?v=C9Q75lGBJRQ', '{}', null, '총채벌레·작은뿌리파리 — 박멸킹', 'dof', null),
  ('greenhouse-condensation', '시설하우스 결로·습도 관리 (곰팡이병의 뿌리)', 'common', array['mold', 'growth']::text[], '아침에 비닐·잎에 물방울이 맺히고, 며칠 뒤 잿빛곰팡이·노균병이 온다', '밤새 식은 하우스 안 수증기가 새벽에 잎에 맺힙니다. 잎이 젖어 있는 시간이 곰팡이병을 키웁니다.', array['해 뜨고 1시간 안에 짧게 환기해 습한 공기를 내보냅니다 (온도보다 습도 먼저)', '보온커튼은 해 뜬 뒤 바로 걷고, 바닥 멀칭으로 토양 수분 증발을 줄입니다', '온습도계를 작물 높이에 두고 새벽 습도를 봅니다. 90% 넘는 시간이 길면 병이 옵니다']::text[], '시설 곰팡이병의 8할은 결로입니다. 자재보다 환기 시간과 보온커튼 운용이 먼저입니다.', array['온습도', '환기', '유동팬', '제습', '결로', '보온커튼', '센서']::text[], false, true, 'https://www.youtube.com/watch?v=uQFZ71_USw4', '{}', null, '딸기하우스 수분·습도 관리', 'dof', null),
  ('greenhouse-heating-prep', '시설하우스 보온·난방 준비', 'common', array['growth']::text[], '첫 추위 전에 이중비닐·보온커튼·난방기를 점검해야 저온 피해를 막는다', '11월 첫 한파에 보온이 안 돼 있으면 생장점이 멈추고, 회복에 2~3주가 걸립니다.', array['이중비닐·보온커튼 찢어진 곳 보수, 출입구 틈새 막기', '난방기 시운전과 연료 점검, 온도 센서 위치 확인(작물 높이)', '작물별 야간 최저온도 기준을 정하고 알람 설정']::text[], '보온은 설비 문제입니다. 추위 오기 전 점검이 난방비보다 쌉니다.', array['난방', '보온', '커튼', '이중비닐', '온풍기', '열풍기', '온도', '센서', '알람']::text[], false, true, 'https://www.youtube.com/watch?v=wKXFlPAYMiI', '{}', null, '겨울철 하우스 난방비 걱정 끝', 'kaftv', null),
  ('greenhouse-salt-ec', '연작 하우스 염류 장해 (EC 과다)', 'common', array['wilting', 'yellow-leaf', 'root']::text[], '물을 줘도 시들고 잎 가장자리가 타며, 흙 표면이 하얗게 된다', '해마다 준 비료가 하우스 안에 쌓여 뿌리가 물을 못 빨아들입니다. 비가 안 들어오는 시설에서 특히 심합니다.', array['토양 EC를 재 봅니다. 작물마다 다르지만 2.0을 넘으면 의심', '담수 세척이나 제염 작물(옥수수·수단그라스) 재배, 유기물 투입', '정식 전 토양 검정을 받고 밑거름을 줄입니다']::text[], '염류 장해는 영양제를 더 준다고 낫지 않습니다. 빼는 관리가 답입니다.', array['EC', '염류', '토양개량', '유기물', '미생물', '토양 검정']::text[], false, false, 'https://www.youtube.com/watch?v=xkAhZSXWEJs', '{}', null, 'EC·염류 고민 없이 농사 짓는 방법', 'kaftv', null),
  ('melon-seedling-prep', '참외·수박 접목묘 준비와 육묘', 'melon', array['growth', 'root']::text[], '정식 40~50일 전 접목묘를 예약하고, 육묘상 온도·습도를 맞춘다', '늦게 주문하면 원하는 품종·대목을 못 받고, 육묘상이 추우면 활착이 늦습니다.', array['품종·대목을 정해 육묘장에 미리 예약 (연작 밭은 덩굴쪼김병 저항성 대목)', '육묘상 바닥 온도 유지, 낮밤 온도차 관리', '정식 전 토양 소독·태양열 소독 여부 결정']::text[], '참외·수박 농사의 절반은 묘에서 결정됩니다. 좋은 묘를 제때 받는 게 첫 자재입니다.', array['접목묘', '육묘', '대목', '참외', '수박', '모종', '육묘상']::text[], false, true, 'https://www.youtube.com/watch?v=2mHdJxr-lV4', '{}', null, '참외 달인들이 말하는 참외 잘 키우는 비법', 'kaftv', null),
  ('leafy-downy-sclerotinia', '상추·엽채 노균병·균핵병', 'leafy', array['mold', 'spots']::text[], '잎에 누런 반점 뒤 흰 곰팡이, 밑동이 물러지며 흰 솜 같은 균사', '저온 다습한 겨울 하우스에서 번집니다. 밀식과 결로가 원인입니다.', array['병든 포기는 즉시 제거, 수확 후 잔재물 치우기', '아침 환기와 멀칭으로 잎·밑동이 젖는 시간 줄이기', '예방 위주 균 관리, 수확 주기가 짧으니 안전사용기준 확인']::text[], '엽채는 수확이 잦아 약을 많이 쓸 수 없습니다. 환기와 잔재물 관리가 자재보다 먼저입니다.', array['노균', '균핵', '살균', '상추', '엽채', '시금치']::text[], false, true, 'https://www.youtube.com/watch?v=EeH1ArY5gbU', '{}', null, '유황 순도 99.5%, 균핵병을 고친다', 'kaftv', null),
  ('strawberry-bee-pollination', '딸기 벌 투입과 수정 관리', 'strawberry', array['growth']::text[], '개화 시작 전 벌통을 넣고, 약제·저온·흐린 날에 벌이 안 나오면 기형과가 는다', '수정은 벌이 합니다. 벌 활동이 떨어지면 기형과·수량 감소로 바로 이어집니다.', array['첫 꽃 피기 전 벌통 투입, 하우스 안에 물·햇빛 자리 확보', '약제 살포는 벌 활동이 없는 저녁에, 벌에 안전한 자재 위주', '흐린 날·저온이 이어지면 보조 수정(바람·붓) 검토']::text[], '벌은 가장 싼 일꾼입니다. 벌을 지키는 운용이 수량을 지킵니다.', array['벌', '수정', '화분매개', '뒤영벌', '꿀벌', '딸기']::text[], false, true, null, '{}', null, null, null, null),
  ('cucumber-tomato-low-temp', '오이·토마토 저온기 생육 정체', 'cucumber', array['growth', 'yellow-leaf']::text[], '해가 짧아지며 생장이 느려지고 잎색이 옅어지며 착과가 떨어진다', '지온·야간 온도 부족과 광 부족이 겹칩니다. 뿌리가 식으면 양분 흡수가 멈춥니다.', array['지온을 먼저 올립니다 (멀칭·바닥 보온). 공기 온도보다 뿌리 온도', '광량 부족 시 보광 검토, 늙은 잎 정리로 빛 들이기', '저온기에는 질소를 줄이고 뿌리 활력 위주로']::text[], '겨울 생육 정체는 영양 부족이 아니라 온도·빛 부족입니다. 비료를 더 주면 오히려 염류만 쌓입니다.', array['지온', '보광', 'LED', '멀칭', '뿌리', '활력', '아미노', '오이', '토마토']::text[], false, true, 'https://www.youtube.com/watch?v=aJ-dfGVkbZQ', '{}', null, '저온 건조기 비료 흡수력을 높여주는 비료', 'kaftv', null),
  ('common-yellow-leaf', '잎이 노랗게 변한다 (작물 공통)', 'common', array['yellow-leaf']::text[], '아래 잎부터인지, 새잎부터인지, 잎맥만 남는지에 따라 원인이 다름', '질소·마그네슘·철 결핍, 과습, 뿌리 손상, 병해 등 원인이 여러 가지입니다.', array['어느 잎부터 노래지는지 사진을 찍어 둡니다 (아래 잎: 질소·마그네슘 / 새잎: 철·황)', '뿌리를 뽑아 색과 냄새를 봅니다. 갈색·냄새면 과습·뿌리병', '원인을 모른 채 영양제를 먼저 주지 않습니다']::text[], '노란 잎은 증상이지 병명이 아닙니다. 어느 잎부터인지가 원인을 가릅니다.', '{}', true, false, 'https://www.youtube.com/watch?v=4X0BQDH2t6w', '{}', null, '마늘 잎이 누렇게 됐나요? 꼭 봐야 할 영상', 'kaftv', null),
  ('common-sudden-wilt', '갑자기 시든다 (작물 공통)', 'common', array['wilting', 'root']::text[], '낮에 시들었다 밤에 회복하다가 결국 말라 죽는다', '뿌리썩음·시들음병·배수 불량·염류 장해·선충 등. 지상부만 봐서는 구분이 안 됩니다.', array['포기를 뽑아 뿌리와 줄기 단면을 봅니다. 갈변·물관 변색이면 병', '주변 포기로 번지는지 며칠 지켜봅니다', '배수와 염류(EC)부터 점검, 그다음 병 진단']::text[], '시듦은 뿌리를 봐야 압니다. 사진 진단이나 문의로 원인을 먼저 가리고 자재는 그다음입니다.', '{}', true, false, 'https://www.youtube.com/watch?v=BwDCsUCozrc', '{}', null, '딸기 시들음병, 엎친 데 덮친', 'kaftv', null)
